async function quote66(entry,exit,east){const now=new Date(),parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:true}).formatToParts(now).map(p=>[p.type,p.value]));const q=new URLSearchParams({handler:'TollCalcPartial',bIntId:entry,eIntId:exit,datePicked:parts.month+'/'+parts.day+'/'+parts.year,timePicked:parts.hour+':'+parts.minute+' '+parts.dayPeriod,rbEastVal:String(east),isCurrent:'true'});let lastError;for(let attempt=0;attempt<2;attempt++){try{const data=await(await upstream('https://vai66tolls.com/Index?'+q)).json();if(typeof data.decToll!=='number'||!Number.isFinite(data.decToll)||data.decToll<0)throw Error('VDOT returned an invalid I-66 price');return data.decToll;}catch(error){lastError=error;}}throw Error('VDOT current I-66 calculator unavailable: '+(lastError?.message||'No current response'));}
function quote495(source,e,id){const dest=e.exits.find(x=>x.id===id);if(!dest)return {id,error:'No direct route'};const rows=dest.ods.map(od=>source.response.find(p=>p.od==='od_'+od));if(rows.some(p=>!p||p.price==null||String(p.price).trim()===''||p.price==='null'||!Number.isFinite(Number(p.price))||Number(p.price)<0))return {id,error:'Price unavailable'};if(rows.some(p=>p.status!=='open'))return {id,error:'Lane status unconfirmed or closed'};return {id,price:rows.reduce((n,p)=>n+Number(p.price),0),sourceTime:rows.some(p=>!p.time||p.time==='null')?null:rows.map(p=>p.time).sort()[0],legs:rows.map(p=>({road:'I-'+p.road,price:Number(p.price),sourceTime:p.time}))};}

export default {async fetch(request){const u=new URL(request.url);try{if(ASSETS[u.pathname]){const a=ASSETS[u.pathname],bytes=Uint8Array.from(atob(a.data),c=>c.charCodeAt(0));return new Response(bytes,{headers:{'Content-Type':a.type,'Cache-Control':'private, max-age=86400'}});}
if(u.pathname==='/api/catalog'){const road=u.searchParams.get('road'),dir=u.searchParams.get('dir');if(['495','95','395'].includes(road))return json({...catalog[dir],entries:Object.fromEntries(Object.entries(catalog[dir]?.entries||{}).filter(([id,p])=>p.path.startsWith(road))),connections:[...eastStops.map(p=>({...p,id:'66e:'+p.id,label:'I-66 east · '+p.label,group:'66e'})),...westStops.flatMap(([id,label])=>[{id:'66w:'+id,label:'I-66 west · '+label+' (express)',group:'66w'},...(['monument','stringfellow'].includes(id)?[]:[{id:'66g:'+id,label:'I-66 west · '+label+' (regular lanes)',group:'66w'}])])]});if(road!=='66')return json({error:'Outside-Beltway feed unavailable'},503);const east=dir==='Eastbound';const html=await(await upstream('https://vai66tolls.com/Index?handler=BeginIntPartial&rbEastVal='+east)).text();return json({entries:coords(html,options(html)),exits:native66Exits[east?'east':'west']});}
if(u.pathname==='/api/exits'&&['495','95','395'].includes(u.searchParams.get('road')))return json({exits:await destinations(u.searchParams.get('dir'),u.searchParams.get('entry'))});
if(u.pathname==='/api/exits'){const east=u.searchParams.get('dir')==='Eastbound';const entry=u.searchParams.get('entry');if(!/^\d+$/.test(entry))return json({error:'Invalid entry'},400);const html=await(await upstream('https://vai66tolls.com/Index?handler=ExitIntPartial&bIntId='+entry+'&rbEastVal='+east)).text();return json({exits:coords(html,options(html)).map(p=>({...p,group:east?'66e':'66w'}))});}
if(u.pathname==='/api/prices'){const road=u.searchParams.get('road'),dir=u.searchParams.get('dir'),entry=u.searchParams.get('entry');const ids=(u.searchParams.get('exits')||'').split(',');const fetchedAt=new Date().toISOString();if(['495','95','395'].includes(road)){const source=await(await upstream('https://expresslanes.com/maps-api/infra-price-confirmed-all')).json();if(source.error!=='0')throw Error('Operator pricing unavailable');const e=catalog[dir]?.entries[entry];if(!e)throw Error('Unknown entry');const allowed=await destinations(dir,entry);const quotes=await Promise.all(ids.map(async id=>{const dest=allowed.find(d=>d.id===id);if(!dest)return {id,error:'No verified connection'};if(!id.includes(':'))return quote495(source,e,id);const base=quote495(source,e,dest.via);if(base.error)return {id,error:base.error};if(id.startsWith('66w:'))return {id,error:'Total incomplete',knownPrice:base.price,sourceTime:base.sourceTime,legs:[...base.legs,{road:'I-66 west express',error:'Live source not connected'}]};if(id.startsWith('66g:'))return {...base,id,legs:[...base.legs,{road:'I-66 west regular lanes',price:0}],note:'Use regular lanes on I-66; no I-66 express toll included'};try{const price=await quote66('3',id.split(':')[1],true);return {...base,id,price:base.price+price,legs:[...base.legs,{road:'I-66 east',price}],note:'Current component estimates; I-66 may change before you reach it'};}catch{return {id,error:'Total incomplete',knownPrice:base.price,sourceTime:base.sourceTime,legs:[...base.legs,{road:'I-66 east',error:'Live price unavailable'}]};}}));return json({quotes,fetchedAt,source:'Express Lanes'});}
if(road!=='66')throw Error('Live data not connected');if(!/^\d+$/.test(entry)||ids.some(id=>!/^\d+$/.test(id)))return json({error:'Invalid route'},400);
const quotes=await Promise.all(ids.map(async id=>{try{return {id,price:await quote66(entry,id,dir==='Eastbound'),dataSource:'VDOT current I-66 calculator'};}catch(error){return {id,error:'Current I-66 estimate unavailable',note:error.message};}}));return json({quotes,fetchedAt,source:'VDOT I-66 calculator'});}
if(u.pathname.startsWith('/api/'))return json({error:'Not found'},404);return new Response(HTML,{headers:{'Content-Type':'text/html;charset=utf-8'}});
}catch(e){return json({error:e.message||'Unable to reach operator. Try again.'},502);}}};
